import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷六","description":"周易經傳集解 - 周易經傳集解卷六","frontmatter":{"title":"周易經傳集解卷六","description":"周易經傳集解 - 周易經傳集解卷六"},"headers":[],"relativePath":"classics/jingchuan-jijie/007.md","filePath":"classics/jingchuan-jijie/007.md"}'),r={name:"classics/jingchuan-jijie/007.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷六",tabindex:"-1"},[n("周易經傳集解卷六 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷六","aria-label":"Permalink to “周易經傳集解卷六”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解泰否卷六 ​宋林栗撰序：卦曰：「履而泰，然後安，故受之以泰。」「泰」者，通也。泰之成卦，履之變也。自履而泰，乾反居下，兌變為坤，上下相易而成卦也。乾反居下，所以交為兌也；兌變為坤，所以順於乾也。夫履也者，自上履下，乾履兌，履虎尾也。說而應乎乾，是故履之而不吾咥也。彼既心說而誠服矣，然其情未交而志未通，是以有虎之象焉。雖不吾咥，亦已危矣。何者？乾履於二而未有以交之也，及乎降尊而就卑，然後上下之情交通而無間，斯可以相安而無不測之虞矣。是故兌之象一也，在履為虎，在泰為妹，由其情異而志殊也，豈不擬諸形容而象其物宜也哉？泰：小往大來，吉，亨。彖曰：「泰，小往大來，吉，亨。」則是天地交而萬物通也，上下交而其志同也。內陽而外陰，內健而外順，內君子而外小人。君子道長，小人道消也。下乾上坤，成卦曰泰者，初為乾，二為兌，三為震，四為坤。乾為父，坤為母。震一索而得男，兌三索而得女。天尊地卑，乾坤定矣；卑高以陳，貴賤位矣。今乾反在下，則是天地易位而上下失序矣。聖人之作易也，何以知其天地之變而不為易位失序者乎？以有震「兌」存乎其間也。震也者，乾坤之始交；兌也者，乾、坤之終合也。始也者，萬物之所以生也；終也者，萬物之所以成也。震上兌下者，歸妹之象也。歸妹，天地之大義也。天地不交，而萬物不興。歸妹，人之終始也。是故天地之始交也，出乎震，發而為雷；其終也，入乎兌，鍾而為澤，皆氤氳之氣也。謂之「交泰」，不亦宜乎？「泰」者，通也。人之血氣流暢，心安體舒，則謂之「泰」，亦取通之義也。「泰，小往大來，吉亨」，何謂也？曰：三陰出而在外，三陽入而居內，陽日以長，陰日以消，陽為大，陰為小故也。以天地言之，則天為大，而地為小。以上下言之，則上為大，而下為小。以陰陽言之，則陽為大，而陰為小。以健順言之，則健為大，而順為小。以君子小人言之，則君子為大，而小人為小。「小往大來」，而系以「吉亨」者，則是天地交而萬物通也，上下交而其志同也。天穹隆而上覆，地旁薄而下承，四時何由而行？萬物何由而生？天氣下降，地氣上騰，氤氳交通，然後四時行而萬物生矣。君尊而在上，臣卑而在下，百工何由而熙？庶事何由而康？上之情達於下，下之情通於上，歡忻相與，然後百工熙而庶事康矣。內陽而外陰，春夏之所以發生也。內健而外順，君子之所以成德也。內君子而外小人，君子道長，小人道消，天下之所以治也。系之吉亨，不亦宜乎？象曰：天地交，泰。後以財成天地之道，輔相天地之宜，以左右民。天者，乾也。地者，坤也。天地交而萬物通，所以為泰也。後者，上也。民者，下也。上下交而其志同，所以為泰也。天地之道，生成是也。春省耕而補不足，秋省斂而助不給，所以財成其道，而左右民也。天地之宜，四時九土是也。析因夷墺，敬授其時；高下肥磽，教之樹藝；所以輔相其宜，而左右民也。天者，君象也。地者，臣民之象也。君者，所以治人也；臣者，所以輔相其君者也；民者，所以翼戴其上者也。而古之王者，憂民之飢而佐之耕，憂民之寒而勸之桑，憂民之暴露而教之乘屋，憂民之勞苦而教之舟車。至於鰥寡孤獨、老弱貧窮，皆使養生送死而無憾，是以君而左右其民也，得夫天地交泰之義矣。孟子曰：「匡之直之，輔之翼之，使自得之，又從而振德之。」此之謂也。益稷篇曰：「予欲左右有民。」武王曰：「天佑下民，作之君，作之師。」天猶佑之，而況君乎？「財」與裁同，古字通用。雜卦曰：「否泰，反其類也。」三陽在下，三陰在上，此其所以為「泰」也。然其在爻，陽反上升，陰反下接，何也？聖人以為陽升陰降，自然之理。若陽降而不能升，陰升而不能降，則是尊卑易位之象，而非上下交感之義也。天地之位，不敢易也，所交者其氣也。君臣之位，不可易也，所交者其情也。故雖「乾」下「坤」上，而六五為君，九二為臣，不可易也。「乾震」之中有「兌」象焉，「坤巽」之中有「艮」象焉。「兌」也者，「坤巽」之類也，而居「乾震」之中；「艮」也者，「乾震」之類也，而在「坤巽」之內，是謂「反其類」者也。以九居二，以六居五，二氣感應，有相與之意焉。謂之陽則其象「兌」也，謂之陰則其數九也，謂之柔則其象「艮」也，謂之剛則其數六也，是謂「反其類也」者。一剛一柔，交錯成卦，三陽以兌而上升，三陰以「艮」而下接，然後「泰」之交爻粲然而可見矣。初九：拔茅茹以其匯，徵吉。象曰：「拔茅」「徵吉」，志在外也。初九，「乾」也，以陽居剛而在下卦之下，應乎六四之「坤」，而連九三之震，故曰「拔茅茹以其匯，徵吉」。「震」為萑葦，故有茅象。五體「艮」，「艮」為首，有拔之之象。茅之為物，潔白而叢生者也，可以縮酒而祭天地，可以包土錫命諸侯。生於山林藪澤之中，而用於宗廟朝廷之上，賢人君子之譬也。「拔茅」者，舍短而取長，人君舉賢之譬也。「茹」，茅之秀者，以其可茹，故謂之「茹」。「匯」，猶類也，以其叢生，故謂之「匯」。拔其茹，則其根牽引成叢而起，君子見用，則引其類而升之譬也。六五為「艮」，下連於三。九三為「震」，下連於初。五之可拔，及三而已，而茹之所連，遂及於初。蓋三陽同志而升，初九與九三同體乎「乾」，故曰「成泰」。以上下交為義。六四者，初九之配也。六五者，九二之配也。言初九而不及四六，言六五而不及九二，乃以九三言，其義何也？曰：「泰」之言通也，六爻以相通為義者也。六五者，「泰」之君也。使五之拔止於九二，而九三、初六各從其配，何以為泰乎？六四者，五之近臣也。使初之從止於六四，而六五、上六各分其應，是君臣俱有黨也，何以為泰乎？故曰：「天地交而萬物通也，上下交而其志同也。」三陽同志而上升，三陰同志而下接，六爻同志而相與，所以為「泰」之時也。故於初陽進之始，取諸拔茅連茹之象焉，以明三陽同志而升故也。三之言眾也，舉一賢則眾賢萃於朝，斯之謂「泰」矣，故曰「吉」。子曰：「拔茅徵吉，志在外也。」言三陽在內，而其志在外也。三陽在內而其志在外，故以其類而徵吉也。九二：包荒，用馮河，不遐遺。朋亡，得尚於中行。象曰：「包荒」，「得尚於中行」，以光大也。九二，「兌」也，以陽居柔，而在下卦之中，應乎六五之「艮」，故曰：「包荒，用馮河，不遐遺，朋亡，得尚於中行。」初為「乾」，「乾」為「郊」。二為「兌」，「兌」為澤。三為「震」，「震」為萑葦。郊野之外，水澤所鍾，而萑葦茅茨生焉，「荒」之象也。「乾」為人，「兌」為澤，「震」為足，水澤之上，人徙涉焉，「馮河」之象也。「乾」為郊野，遐之象也。「坤」為眾，朋之象也。「荒」者，茅塞而不治，人之所棄也。「馮河」者，進取而不顧，人之所疾也。「遐」者，疏遠而易遺；「朋」者，親近而難忘者也。惟六五之君，以柔居尊，不畜三陽，而返其「坤」「巽」之類。故「荒」者吾能包之，「馮河」吾能用之。疏遠之賢無遺於野，而朋比之眾自散於朝，則可謂皇極之君矣。「尚」猶配也。「中行」謂二也。有皇極之君，必有中行之臣說而應之，故六五得配於九二，以成交泰之治也。何者？以六居五，以九居二，履中正之位，無剛柔之偏故也。孔子曰：「不得中行而與之，必也狂狷乎！徵者進取，狷者有所不為也。」又曰：「道之不行也，我知之矣。賢者過之，不肖者不及也。」荒與馮河，孔子之所謂狂狷，過不及者歟！何者？以陽居剛而不得乎中故也。刳胎殺天，則麒麟不至；覆巢毀卵，則鳳凰不翔。西伯養老，而太公歸之；燕昭禮士，而樂毅從之。「包荒得尚於中行」，不亦宜乎？子曰：「包荒得尚於中行，以光大也。」其六五之謂矣。二五相與，剛柔迭居，是以互言其義也。九三：無平不陂，無往不復。艱貞無咎。勿恤其孚，於食有福。象曰：「無往不復」，天地際也。九三下體為「乾」，上體為「震」，以陽居剛而在下卦之上，應乎上六而承乎六四。二爻皆「坤」，而四又「巽」也。故曰：「無平不陂，無往不復。」陽為平，陰為陂；陽為往，陰為復。三陽之進，至是極矣。當「泰」之初，陽自下升，故不嫌於居剛。至於九二，居柔得中，上應六五，以成交泰之道。古之明君良臣，同德相須，無為而治者，由此也。至於九三，道已隆矣，時已極矣，持盈守成，茲為難矣。而三又以陽居剛，行過乎中，體乎剛健，而資之以太躁。及其勢力進而迫之，以乾迫坤，以震迫巽，以九三迫四，以至剛迫至柔，物極則反，理勢然也。高岸為谷，深谷為陵，無平不陂之義也。寒往則暑來，暑往則寒來，無往不復之義也。以坤易乾，以巽易震，平者陂矣，往者復矣，而否之象見矣。是以聖人憂之，而為之戒焉。若曰勿極其平，庶幾不陂；勿窮其往，庶幾不復。世之君子，當極盛之時，視其力足以誅鋤小人，視其威足以鞭笞四夷，必極其平、窮其往而後已。此小人之所以複用，而四夷之所以復強也。子曰：「人而不仁，疾之已甚，亂也。」故曰：「艱貞無咎，勿恤其孚，於食有福。」書曰：「無疆惟休，亦大惟艱。」又曰：「無疆惟休，亦無疆惟恤。」恤之言憂也。勿者，甚之之辭也，猶言太極矣，能勿憂乎？以乾迫坤，以震迫巽，可謂無往矣。以坤遇乾，以巽遇震，可謂其孚矣。弗圖其難，則患生於所易；弗虞其變，則憂在於所孚。方泰之時，惟見其易，豈知其難？惟信其孚，豈慮其變？是以平陂往復，常在循環反掌之間耳。古之君子，為能見其易而思其難，見其孚而不忘其恤。以艱為貞，則可以免於咎；以恤為孚，則可以安樂飲食而保其福祿也。故曰：「知難無難，知憂不憂」，豈不信哉？子曰：「無往不復，天地際也。」為其乾坤相際之處，陰陽往復之爻，故系之以如此之辭也。六四：翩翩，不富以其鄰，不戒以孚。象曰：「翩翩」「不富」，皆失實也。「不戒以孚」，中心願也。六四上體為「坤」，下體為「巽」，以陰居柔而在上卦之下，乘乎九三而應在初九，二爻皆「乾」，而三又「震」也，故曰：「翩翩，不富以其鄰」。「翩翩」，群飛而上之象。三陽在下，以其匯而升，故有「拔茅」之象。三陰在上，以其群而下，故有「翩翩」之象焉。「鄰」謂四也，自六五而言之，四上皆鄰也。陽為富貴，陰為虛貧。「小畜」之九五，能用其鄰者，為其富也。今以六居五，則不富矣。所以能用其群者，豈非其中心之所願故歟？故曰：「不戒以孚」。「坤」之從「乾」，「巽」之從「震」，「艮」之從「兌」，其自志願，不待告戒而自孚矣。子曰：「翩翩不富」，皆失實也。「不戒以孚」，中心願也。或曰：「九三、六四，其為孚一也。三言勿恤其孚，四言不戒以孚，其不同何也？」曰：「三者，陽進之終，不憂則變矣。四陰之始降，又何戒之有哉？」或曰：「乾下坤上，所以為泰之始。子之論陽升陰降，則是不交也，而何以為泰乎？」故舊說皆雲：「陽樂上覆，陰樂下復。」九三過中，有平陂往復之義。至於四六，則又過矣。故三陰同志而下復其所，是「泰」極則「否」之義也。曰：未之思耳。九二「包荒，得尚於中行」，六五「歸妹以祉，元吉」，學者莫能改也。初九「拔茅茹以其匯，徵吉」，學者亦莫能改也。奚獨疑於四哉？若初九「以其匯徵」，六四復其所而不應，何由吉而亨乎？自三以往，「泰」即為「否」。如六五者，又過於四，何以「元吉」乎？陰陽相求，物之情也。何以言「陽樂上覆，陰樂下復」乎？故曰：天地之位，不可易也，所交者，其氣也。君臣之位，不可易也，所交者，其情也。六四上承六五，下接九三，而應於初九，體乎柔巽，以逮三陽，其近臣之象乎！或曰：「九三剛中，與五為配，大臣之象也。又以六四當之，何以別其人乎？」曰：剛中者，所以輔弼其君也；柔巽者，所以汲引乎賢者之大臣也。豈一而足哉？記曰：「大臣不可不敬也，邇臣不可不慎也。」學者又何疑焉？六五：帝乙歸妹，以祉元吉。象曰：「以祉元吉」，中以行願也。六五，「艮」也，以陰居剛，而在上卦之中，應乎九二之「兌」，故曰「帝乙歸妹」。五居天位，有「帝乙」之象。「兌」為少女，有「歸妹」之象。說者皆以「歸妹」為嫁女之義。伊川程氏曰：「帝乙，商之賢王，始制王姬下嫁之禮法者也。」愚竊謂不然。帝乙居尊而嫁其女於二，二之象為君乎？抑為臣乎？以為臣，則女之所歸，有夫道矣。以為君，則帝乙在上，而二又為君，於人無據矣。「妹」者，「兌」也，而帝乙之所自出，在室曰「女」，在塗曰「婦」，則五當為「兌」，不在二矣。以意逆之，帝乙行親迎之禮者也。六五為帝，九二為妹，賢人君子檢飭其身，修之於家，行之於鄉，凜乎如季女之不可犯也。而六五之君，能降尊而為之禮，然後九二之臣說而應之。「艮」「兌」相與，交感之象也。「帝乙歸妹」，不其然歟？故曰：「以祉元吉。」五以祉而錫二，二以祉而歸之上，上下相與，可謂「元吉」矣。子曰：「以祉元吉，中以行願也。」二五得中而行其所願，元吉也宜哉！上六：城復於隍，勿用師，自邑告命，貞吝。象曰：「城復於隍」，其命亂也。上六，「坤」也。以陰居柔，而在一卦之上，應乎九三之「震」，故曰：「城復於隍。」「坤」為土，「震」為動，有版築之象焉。高城而濬隍，增其土而穴其上，穴之不已，「城復於隍」矣。此乃「泰」極則「否」之義也。「坤」本在下而位於上，猶之以土為城也。至於上六，極其高矣，而九三之「震追」而迫之，「其復於隍」，不亦宜乎？國之興也，其累之非一日，窮其力而壞之者多矣，可不戒哉！「泰」之為卦，以「乾」下「坤」上而成。其在六爻，以陽升陰降為義。初四升降之始，故有拔茅翩翩之辭。二五升降之中，故有「歸妹」「得尚」之義。三上升降之極，故有「往復城隍」之象焉。故曰：「勿用師，自邑告命，貞吝。」「坤」為眾，為邑，故有「用師自邑」之象焉。行師出令，國之所以廢興存亡者也。不出於國而出於邑，為「貞吝」之道也。子曰：「城復於隍，其命亂也。」夫為城者，豈故穴而頹之哉？以其命出於眾，無所適從。千人築之，萬人穴之，城之不頹，未之有也。或曰：城復於隍，亂亡之象矣。不曰「兇」而曰「吝」，何哉？曰：「泰」之六爻，皆有相應之義，至於上六，窮上及下，乃入於「否」，亂則成矣，而未至於亡也。然則「城復於隍」，其紀綱敗壞之象乎？用眾而眾不從，告命而命不行，以是為羞吝而已。吝猶不改，兇可逃乎？序卦曰：「泰者，通也；物不可終通，故受之以否。」「否」之成卦，「泰」之反也。乾下坤上，所以為「泰」也；「坤」下乾上，所以為「否」也。「泰」者，通也；「否」者，塞也；「泰」者，闢也；「否」者，闔也。一通一塞，一闔一闢，如寒暑之相推，如昏明之相代，物理之常，雖天地聖人有不能逃也。所貴乎聖人者，為能消息盈虛，知進退存亡而不失其正，乘其機會，有以變而通之。如使天地無時而不交，萬物無時而不通，則是有旦而無夜，有春夏而無秋冬也。故曰：物不可以終通，受之以「否」，其「與時偕極」之義乎？否之匪人，不利君子貞，大往小來。彖曰：「否之匪人，不利君子貞，大往小來」，則是天地不交而萬物不通也；上下不交，而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子。小人道長，君子道消也。下坤上乾，成卦曰「否」者，初為坤，二為艮，三為巽，四為乾。乾為天，巽為風，艮為山，坤為地。上天下澤，其卦為履。上天下地，不曰卑高以陳乎？聖人取諸貴賤之位，而遂以為上下不交者，以有「巽」「艮」存乎其間也。巽為風，艮為山，艮為少男，巽為長女。山之與風，少男之與長女，異乎交感之義也。坤下艮上為剝，巽下乾上為姤。姤者，柔遇剛也。剝者，柔變剛也。皆陰長陽消之象也。謂之否塞，不亦宜乎？是故「姤」者，否之始；「剝」者，否之終也。「否之匪人，不利君子貞，大往小來」，何也？曰：天地泰矣，變而否之者，非小人為誰？不謂之小人而謂之匪人者，甚之之辭也。今夫內陽而外陰者，人之受形而生也。內柔而外剛者，人之所以氣反而死也。是故剛健以立身，柔巽以接物，斯之謂人道矣。反此者，非人也。在易，初二為地，三四為人，五上為天。泰之三四，內陽而外陰，天地之所以交，而人道之所以立也。今否之三四，內柔而外剛，反天地之和，變人理之正，謂之匪人，不亦宜乎？自昔天下之亂，未嘗不起於民窮而主不恤，下怨而上不知。其所以下怨而上不知者，必有邪佞匪人壅蔽於其間也，飛廉、惡來、趙高、石顯其人也。自今而視之，其小人乎？其匪人乎？六三之謂匪人，九四之謂君子，匪人得志，其不利於君子必矣。然而君子者，豈以其不利而易其節歟？貞固守之，斯謂之君子也矣。三陽在上，不交於陰，君子之貞，亦如是爾。臨川王氏曰：否之匪人者，天也，非人之所能為也。嗚呼！不幾於一言而喪邦乎？大往小來者，泰之反也。天氣不下降，則雲雨不施；地氣不上騰，則大明不升，萬物之所以不通也。下之情不上達，則君疑其臣而惡其民；上之情不下通，則民怨其君而疾其長，天下之所以無邦也。內陰而外陽，秋冬之所以斂藏也。內柔而外剛，小人之所以敗德也。內小人而外君子，小人道長，君子道消，天下之所以亂也。或問「消長」。曰：長如草木之長，消如霰雪之消。堯、舜之時，比屋可封。文、武之興，民皆好善。非盡滅小人而更生君子也，君子道長，小人變而為之也。桀、紂之時，比屋可誅。幽、厲之興，民皆好暴。非盡滅君子而更生小人也，小人道長，君子化而為之也。董仲舒曰：「積善在身，猶長日加益，而人不知也；積惡在身，猶火消膏，而莫之覺也。」此消長之義也。自復至泰，自姤至否，陰陽消長，應其爻乎？象曰：天地不交，否。君子以險德避難，不可榮以祿。天地不交，其卦為「否」。君子觀此象，以險德避難，雖欲高爵厚祿系而維之，有不可得矣。世之君子，當無道之朝，進不得行其志，徒觸險難之機，然而莫之避者，非無周身之智也。膏粱芻豢，必求口體之充；金玉錦繡，必飽妻子之慾。利害迫於中，而榮辱眩其外，故貪祿而忘反，以及於禍也。險德避難，不亦可乎？孔子曰：「邦無道，谷，恥也。」又曰：「邦無道，富且貴焉，恥也。」既以為恥矣，又可得而榮之哉？雜卦曰：「否泰，反其類也。」「否」之「反其類」，與「泰」一也。坤、巽之中有「艮」象焉，乾、「震」之中有「兌」象焉。兌也者，坤、巽之類也，而居乾、震之中。艮也者，乾、震之類也，而在坤、巽之內。是謂「反其類」者也。以九居二，以六居五。謂之陽，則其象「兌」也。謂之陰，則其數九也。謂之柔，則其象「艮」也。謂之剛，則其數六也。是謂「反其類」者也。然「泰」以天地交為義，所謂反者，陽升而陰降也。「否」以不交為義，所謂反者，艮下而兌上也。艮下兌上，雖有交感之義，而九五、六二則無相與之意焉。是故否之六爻，上下不交，三陰合而與否者也，三陽合而傾否者也。六以二反其類，故有「包承」之象。九五反其類，故有「其亡」之戒也。或曰：子以艮、巽不合，明乾、坤之不交，而以艮、兌言交感之義，毋乃自為不情歟？曰：重卦之坤、艮、巽、乾著矣，所謂「兩儀生四象」也。反而取之，益之以乾、兌、震、坤，然後八卦具而六爻之情狀畢見矣，所謂「四象生八卦」也。卦之相推，取諸四象，而六爻之相錯，得不以八卦定其吉凶乎？此序卦、雜卦之所以異也。初六：拔茅茹，以其匯，貞吉，亨。象曰：「拔茅」「貞吉」，志在君也。初六，「坤」也。以陰居剛，而在下卦之下，應乎九四。四，「乾」「震」也。在「否」之時，「乾」、「坤」不交，故曰：「拔茅茹，以其匯，貞。」小人用事，固已迸逐君子而外之矣。然陰柔之資，識慮寡暗，外無以服眾心，內無以決庶務，其勢必將挽回君子，以為己之用。君子者，苟貪利而從之，是亦小人而已矣。故因九四之不交於初，而著其義焉。初六、六三以陰居剛，其聲音顏色𧦧𧦧然，雖欲挽回君子，宜其望而去之矣。必也六二之柔順，包而成之，庶幾君子之肯從也。四體「震」，「震」為萑葦；二體「艮」，「艮」為子，故有「拔茅」之象焉。二、四同體，二之所拔者，四也。拔茅者自上而揠之，則其根牽引成叢而起，固其宜也。自下而挽之，未有能拔之者也。以其匯貞，不亦宜乎？故曰：吉亨。於初言「徵」，則其類無不徵矣；於四言「貞」，則其類無不貞矣。尺蠖之屈，以求信也；龍蛇之蟄，以存身也。欲存其身而不能蟄，無自而能存矣；欲求其信而不能屈，無自而能信矣。以其「匯貞」而系之「吉亨」，不亦宜乎？子曰：「拔茅貞吉，志在君也。」所謂君者，九五之謂乎？九四之類，志皆從五，而六二之徒，欲挽而取之，不可得矣。六二：包承，小人吉，大人否，亨。象曰：「大人否，亨」，不亂群也。六二，「艮」也。以陰居柔，而在下卦之中，應乎九五之「兌」，故曰「包承」。陰為虛，陽為實；陰為卑，陽為尊。以虛而包實，以卑而承尊，故二之與五，有「包承」之象矣。「艮」為山，「兌」為澤，澤在山上，又有「包承」之象焉。當「否」之時，下卦二陰皆小人也。而六二以陰居柔，體「艮」而得中，獨能反其朋類，以包承九五，故曰：「小人吉，大人否，亨。」以陰柔之資，而欲為剛健之事，必不可矣。惟能用其柔順以包容而承事焉，小人之行，於斯吉矣。然九五之大人，為以其善事，己而下與之交，則小人之黨日盛，而君子之道無由亨也。必因時而「否」焉，斯可以全君子之群，而不亂於小人之黨。「否」之而「亨」，不亦宜乎？或曰：所以為否者，上下不交也。以否濟否，何由亨乎？曰：三陽在外，而三陰在內，君子為客，而小人為主。若又與之交，則是與之為「否」也。陰日以長，陽日以消，由「否」而為「剝」，無所不至矣。三陽同志，與時俱否，須事之會，從而傾之，斯為「亨」矣。故子曰：「大人否，亨，不亂群也。」六三：包羞。象曰：「包羞」，位不當也。六三上體為「巽」，下體為「坤」，以陰居剛而在下卦之上，近於九四而應在上六，二爻皆「乾」，而四又「震」也。「包羞」，「坤」為囊，「巽」為伏，故有「包羞」之象。三以陰柔不中而竊處非據，欲以包三陽，以「坤」包「乾」，以「巽」包「震」，而三陽同志皆莫之與，且將協力而傾之。三之所包，得羞而已。故子曰：包羞，位不當也。否之時，六三不當其位，而遏三陽之衝，為否之至也。彖之所謂「匪人」者，斯之謂與？九四：有命無咎，疇離祉。象曰：「有命無咎」，志行也。九四上體為「乾」，下體為「震」，以陽居柔而在上卦之「巽」，近為六三，而應在初六，二爻皆「坤」，而三又「巽」也，故曰：有命無咎。方「否」之時，三陰進而消陽，四當其衝，以「乾」遇坤，以「震」遇巽，而六二之「艮」又將挽而拔之，宜若有咎矣。然四體乎乾震，其志上行，當三陰之進，屹然獨立，謂夫窮達死生，我則有命，是以求福而不回，見危而不懼，獨以其身當橫流之衝，以俟休否。不期三陽同志，否終則傾，斯為無咎矣。故曰：「疇離祉」。「疇」，類也。「離」，麗也。瓶罄則罍恥，唇亡則齒寒。四之知命，豈徒無咎而已。三陽之疇，皆得麗其祉福焉。子曰：「有命無咎，志行也。」君子志在行道，豈以小人之奉承而易其守哉？或曰：泰至上六而復變，否至九四而已革，何哉？曰：「泰」以上下交為義，陰陽志同，故初與四、二與五交而成「泰」。至其極，則三與上交，而義以變矣。「否」以不交為義，陰陽異志，故三陰合而為「否」，三陽合而傾否。「否」至上九而後傾，而四之志則同矣。九五，休否，大人吉。其亡其亡，繫於苞桑。象曰：「大人」之「吉」，位正當也。九五，「兌」也。以陽居剛，而在上卦之中，應乎六二之「艮」，故曰「休否」。「休」，息也。「兌」為說，「艮」為止，故有「休否」之象。當「否」之時，上下不交，而有九五之大人出而救之，本剛健之資，而體乎和說之道，上比群陽，而下應於二，然後民有息肩之所，故「大人吉」。「大人」者，以天下為心者也。視天下之溺猶己溺之，視天下之飢猶己飢之也。出而「休否」，斯為吉矣。故又曰：「其亡其亡，繫於苞桑。」桑之木，深根而難拔者也。「苞」，叢生也。九四為震，「震」為木，三陽同志，故有「苞桑」之象焉。六二在「否」之世，小人之能包承者也。五不之應，則無以休天下之否。然受其包承，則小人將遂得志矣。惟九五之大人，能與三陽同志，兢兢朝夕，畏小人之為禍，雖居九五之尊，而常有「其亡」之戒，然後能繫於苞桑，以自固焉。「震」，東方也，在草為茅，在木為桑。三陽同志，在茅為匯，在桑為苞。言其枝則取諸茅，言其系則取諸桑也。知此者，可以言象矣。子曰：「大人之吉，位正當也。以其位之正當，是以謂之大人。以其位之不當，是以謂之匪人也。」又曰：「危者，安其位者也；亡者，保其存者也；亂者，有其治者也。是故君子安而不忘危，治而不忘亂，是故身安而國家可保也。」唐明皇親平內難，憲宗剗削方鎮，可謂休否之大人矣。開元之治，壞於李林甫、楊國忠；元和之功，敗於皇甫鏄、李逢吉。蓋不念其亡，而昧苞桑之義也，可不戒哉！上九：傾否，先否後喜。象曰：否終則傾，何可長也？上九，「乾」也。以陽居柔，而在上卦之上，應乎六三。三，「坤」「巽」也，故曰「傾否」。天傾西北，「乾」為天，為西北之卦，故有「傾否」之象。當否之世，乾坤不交，至其極也，自上而下，則傾否之象也。六三在否，乘時而竊位，上下之與，蓋俟時而傾之矣。決水於千仞之溪，建瓴於高屋之上，其傾否之勢乎？故曰「先否後喜」。上卑下高，故先否；自上而傾，故後喜也。或曰：「九五非救否者與？」曰：五，傾否之主也。世方否塞，有大人者出而救之，汔可小休而已。至於上九，時已極矣，勢已隆矣，從而傾之，若決江河，莫之能御矣。武王克商，散鹿臺之財，發巨橋之粟，驅飛廉、惡來於海隅而戮之，盪滌氛妖，宣暢湮鬱，傾否之義，其斯之謂矣。子曰：「否終則傾，何可長也？」蓋所以勉君子為善之心，懲小人貪亂之志，可謂深切著明矣。物極則反，道窮則變。泰之君子艱貞，否之小人包羞，下卦之中也。及乎上卦之終，則泰復而否傾矣。周易經傳集解卷六。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
